function handleThrow(mc)
{
   var _loc2_;
   var _loc3_;
   if(mc._x > 413 && mc._x < 513)
   {
      if(mc._y > 22 && mc._y < 58)
      {
         background_mc.funnel_mc.gotoAndPlay(2);
         if(foreground_mc.lightmachine_mc.bigbulb_mc._currentframe == 2)
         {
            foreground_mc.lightmachine_mc.bigbulb_mc.gotoAndStop(1);
            foreground_mc.lightmachine_mc.boxtop_mc.gotoAndStop(1);
