         _loc3_ = _loc2_ - 60;
         if(_loc2_ > 60)
         {
            background_mc.loadbar_mc.gotoAndPlay(_loc3_);
         }
         else
         {
            background_mc.loadbar_mc.gotoAndPlay(1);
         }
         if(background_mc.loadbar_mc._currentframe < 40)
         {
            foreground_mc.lightmachine_mc.smallbulb04_mc.gotoAndStop(1);
         }
         if(background_mc.loadbar_mc._currentframe < 80)
         {
            foreground_mc.lightmachine_mc.smallbulb03_mc.gotoAndStop(1);
         }
         if(background_mc.loadbar_mc._currentframe < 120)
         {
            foreground_mc.lightmachine_mc.smallbulb02_mc.gotoAndStop(1);
         }
         if(background_mc.loadbar_mc._currentframe < 160)
         {
            foreground_mc.lightmachine_mc.smallbulb01_mc.gotoAndStop(1);
         }
         mc._visible = false;
      }
   }
}
function startRoom()
{
   SHELL.addListener(SHELL.PLAYER_MOVE,handleUpdatePlayer);
   SHELL.addListener(SHELL.PLAYER_FRAME,handleUpdatePlayer);
   SHELL.addListener(SHELL.UPDATE_PLAYER,handleUpdatePlayer);
   SHELL.addListener(SHELL.ROOM_DESTROYED,handleRoomDestroyed);
   SHELL.addListener(SHELL.COIN_DIG_UPDATE,handleCoinReward);
   if(SHELL.isItemInMyInventory(PIN_ID_NUMBER))
   {
      boulderBlock_mc.play();
      triggers_mc.pool_mc.triggerFunction = function()
      {
         ENGINE.sendJoinRoom("lake",100,275);
      };
   }
   coinAnimHolderClip._visible = false;
}
function handleUpdatePlayer(event)
{
   if(SHELL.getMyPlayerId() != event.player_id)
   {
      return undefined;
   }
   var _loc2_ = false;
   var _loc1_ = SHELL.getPlayerObjectById(event.player_id);
   var _loc3_ = SHELL.getSecretFrame(_loc1_.player_id,_loc1_.frame);
   if(dig_area_mc.hitTest(_loc1_.x,_loc1_.y))
   {
      if(_loc1_.frame == DANCE_FRAME && _loc3_ != _loc1_.frame)
      {
         if(_loc1_.hand == SHOVEL_ID || _loc1_.head == HARD_HAT_ID[0] || _loc1_.head == HARD_HAT_ID[1] || _loc1_.head == HARD_HAT_ID[2] || _loc1_.head == HARD_HAT_ID[3])
         {
            _loc2_ = true;
         }
      }
   }
   if(_loc2_ && timeoutID == INVALID_TIMEOUT_ID)
   {
      timeoutID = setInterval(checkForReward,REWARD_REQUEST_FREQUENCY);
   }
   else if(!_loc2_ && timeoutID != INVALID_TIMEOUT_ID)
   {
      clearInterval(timeoutID);
      timeoutID = INVALID_TIMEOUT_ID;
   }
}
function checkForReward()
{
   var _loc1_ = ENGINE.getPlayerMovieClip(SHELL.getMyPlayerId());
   if(_loc1_.hitTest(lastDigSpot.x,lastDigSpot.y))
   {
      consecutiveDigCount++;
      if(consecutiveDigCount >= MAXIMUM_DIGS_IN_ONE_SPOT)
      {
         return undefined;
      }
   }
   else
   {
      consecutiveDigCount = 0;
   }
   lastDigSpot = {x:_loc1_._x,y:_loc1_._y};
   SHELL.sendGetCoinReward();
}
function handleCoinReward(event)
{
   if(isNaN(event.numCoins) || event.numCoins < 1)
   {
      return undefined;
   }
   if(!coinAnimHolderClip._visible)
   {
      coinAnimHolderClip._visible = true;
      coinAnimHolderClip.swapDepths(COIN_DEPTH);
   }
   var _loc1_;
   if(event.numCoins >= MIN_COINS_FOR_JACKPOT_AWARD_ANIMATION)
   {
      coinAnimHolderClip.coinRewardAnimClip._visible = false;
      coinAnimHolderClip.superCoinRewardAnimClip._visible = true;
      _loc1_ = coinAnimHolderClip.superCoinRewardAnimClip;
   }
   else
   {
      coinAnimHolderClip.coinRewardAnimClip._visible = true;
      coinAnimHolderClip.superCoinRewardAnimClip._visible = false;
      _loc1_ = coinAnimHolderClip.coinRewardAnimClip;
   }
   _loc1_.gotoAndPlay("animate");
   _loc1_.coinRewardClip.gotoAndPlay("animate");
   var _loc3_;
   if(event.numCoins < MIN_COINS_FOR_JACKPOT_AWARD_ANIMATION)
   {
      _loc3_ = _loc1_.coinRewardClip.labelClip;
      _loc3_.labelField.text = event.numCoins;
      _loc3_.labelFieldDropShadow.text = event.numCoins;
      _loc1_._x = lastDigSpot.x + COIN_X_OFFSET;
      _loc1_._y = lastDigSpot.y + COIN_Y_OFFSET;
   }
   else
   {
      _loc1_._x = lastDigSpot.x + COIN_JACKPOT_X_OFFSET;
      _loc1_._y = lastDigSpot.y + COIN_JACKPOT_Y_OFFSET;
   }
}
function handleRoomDestroyed()
{
   SHELL.removeListener(SHELL.PLAYER_MOVE,handleUpdatePlayer);
   SHELL.removeListener(SHELL.PLAYER_FRAME,handleUpdatePlayer);
   SHELL.removeListener(SHELL.UPDATE_PLAYER,handleUpdatePlayer);
   SHELL.removeListener(SHELL.ROOM_DESTROYED,handleRoomDestroyed);
   if(timeoutID != INVALID_TIMEOUT_ID)
   {
      clearInterval(timeoutID);
      timeoutID = INVALID_TIMEOUT_ID;
   }
}
